import json

config = {"name": "devrivet", "version": "1.0.0"}
text = json.dumps(config, indent=2)

const text = '{"tags": ["a, ]", "b",]}';

text.replace(/,\s*([}\]])/g, '$1');
// '{"tags": ["a]", "b"]}'  <- the string "a, ]" became "a]"

function removeTrailingCommas(text) {
  let out = '';
  let inString = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (inString) {
      out += ch;
      if (ch === '\\') out += text[++i]; // keep escaped chars, e.g. \"
      else if (ch === '"') inString = false;
    } else if (ch === '"') {
      inString = true;
      out += ch;
    } else if (ch === ',') {
      let j = i + 1;
      while (/\s/.test(text[j] ?? '')) j++;
      if (text[j] !== '}' && text[j] !== ']') out += ch;
    } else {
      out += ch;
    }
  }
  return out;
}

JSON.parse(removeTrailingCommas('{"tags": ["a, ]", "b",]}'));
// { tags: [ 'a, ]', 'b' ] }

import fs from 'node:fs';
import JSON5 from 'json5';

JSON5.parse('{"a": 1,}'); // { a: 1 }
JSON5.parse('[1, 2,]');   // [ 1, 2 ]

const data = JSON5.parse(fs.readFileSync('config.json5', 'utf8'));
fs.writeFileSync('config.json', JSON.stringify(data, null, 2) + '\n');
